-- 内网人工扫描报告 #6309（gg77）原样 DDL，未做任何删改。
-- 用途：v1.6.2.2 DEF-1 验收 C1——普通索引 kcfb_list_info_idx13 的列名 list_unique_num
--       曾使其被误判为 UNIQUE，导致 R054 误报；真唯一索引 idx14 反被顶替而漏检。
-- Table: kcfb_list_info
CREATE TABLE `kcfb_list_info` (
  `lgl_pern_code` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '法人代码',
  `black_list_seq_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '0' COMMENT '黑名单序号',
  `list_stripe` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名单种类',
  `list_tp` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名单类型标识(1-黑名单 ,2-灰名单 ,3-白名单 ,4-其他名单,5-结售汇关注名单 ,...) ',
  `list_main_body_tp` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名单主体类型代码(1-客户号,2-客户中文名（对公和同业）,3-证件种类+证件号码,4-客户账号,5-联系电话（提示）及相关组合) ',
  `cust_num` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户编号',
  `cust_tp` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户类型代码(03-同业客户,01-对私客户,02-对公客户,4-联名客户,5-潜在客户,...) ',
  `cust_chins_nm` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户名称',
  `lgl_rprtv` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '法定代表人',
  `docs_catg` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证件类型代码',
  `docs_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证件号码',
  `cust_acct_num` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户账号',
  `card_tp` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行卡类型标识(%-所有卡种,01-借记卡) ',
  `chnl_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '渠道代码',
  `chnl_set` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '渠道集合',
  `list_deal_way` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名单处理方式标识',
  `txn_grp_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '交易组别列表',
  `prod_grp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '产品组别',
  `txn_code_set` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '交易码集合',
  `txn_tp_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '交易类型列表',
  `intt_org` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发起组织标识(1-人民银行,2-证监会,3-银监会,4-银联,5-美联储,...) ',
  `nat_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '国家地区代码(ABW-阿鲁巴,AFG-阿富汗,AGO-安哥拉,AIA-安圭拉,ALB-阿尔巴尼亚,...) ',
  `forbid_busi` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '客户禁止业务类型代码(1-全部,2-按柜面交易码禁止,4-按交易组别禁止,5-按产品组别禁止,6-按交易类型禁止,...) ',
  `fincl_org_code` varchar(14) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '金融机构编号',
  `fincl_org_nm` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '金融机构名称',
  `black_list_keywd` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '黑名单关键字',
  `cntct_pern_nm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联系人名称',
  `cntct_pern_cntct_tel` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联系人电话号码',
  `black_list_ste` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '黑名单状态标识(1-有效,2-无效) ',
  `gen_dt` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '生成日期',
  `gen_tm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '0' COMMENT '生成时间',
  `gen_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '生成原因',
  `guardn_nm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发起组织人员名称',
  `tel_num` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '电话号码',
  `eff_tm` varchar(22) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '生效时间',
  `invld_tm` varchar(22) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '失效时间',
  `cust_risk_lv` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名单风险级别标识(0-未评定,1-低风险,2-中低风险,3-中风险,4-中高风险,...) ',
  `spare_fld_200` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段',
  `spare_data_225` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '备用数据',
  `fld` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '字段',
  `fld_dsc` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '字段描述',
  `black_list_remks_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '黑名单备注信息',
  `crea_dt` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建日期',
  `crea_tm` bigint DEFAULT '0' COMMENT '创建时间',
  `crea_org` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建机构编号',
  `crea_tlr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建人柜员号',
  `crea_chnl` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建渠道代码',
  `crea_athrzn_tlr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建授权人柜员号',
  `crea_tlr_rung_num` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '创建柜员流水号',
  `mntnc_chnl` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '维护渠道代码',
  `mntnc_athrzn_tlr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '维护授权人柜员号',
  `mntnc_tlr_rung_num` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '维护交易流水号',
  `list_unique_num` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '名单唯一标识码',
  `txn_lgl_pern_code` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '交易法人代码',
  `br_id` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '分行标识',
  `mntnc_tlr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '维护人柜员号',
  `mntnc_org` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '维护机构编号',
  `mntnc_dt` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '维护日期',
  `mntnc_tm` varchar(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '维护时间',
  `tmstp` bigint DEFAULT '0' COMMENT '保存时间',
  `rec_ste` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '记录状态标识(0-正常,1-删除) ',
  `affr_ste` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'O' COMMENT '事务状态标识(O-正常,T-在途,P-冲账预处理) ',
  `glbl_affr_rung_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '全局事务流水号',
  `affr_ste_upd_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '事务状态更新唯一编号',
  `data_upd_tmstp` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '数据更新时间',
  `record_change_tp` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '记录变更类型标识(N-普通交易,R-冲正交易) ',
  `spare_fld_01_32` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段01',
  `spare_fld_02_32` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备用字段02',
  PRIMARY KEY (`black_list_seq_num`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx2` (`cust_num`),
  KEY `kcfb_list_info_idx4` (`cust_acct_num`,`cust_chins_nm`,`list_tp`,`black_list_seq_num`,`rec_ste`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx6` (`docs_num`,`cust_chins_nm`,`docs_catg`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx7` (`tel_num`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx8` (`cust_acct_num`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx9` (`cust_num`,`list_main_body_tp`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx10` (`cust_chins_nm`,`list_main_body_tp`,`lgl_pern_code`),
  KEY `kcfb_list_info_idx11` (`docs_num`,`list_main_body_tp`,`lgl_pern_code`,`black_list_ste`,`rec_ste`),
  KEY `kcfb_list_info_idx13` (`list_unique_num`,`lgl_pern_code`),
  UNIQUE KEY `kcfb_list_info_idx14` (`black_list_seq_num`,`list_main_body_tp`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='名单信息登记簿' shardkey=black_list_seq_num